// PLACEHOLDER: Ready to be wired to Gmail Trigger / IMAP read
// When Gmail/IMAP credentials are provided, this node reads new unread emails from the outreach inbox.
// For now, passes an empty array until active mailbox credentials are supplied.
return [];

const items = $input.all();

return items.map(item => {
  const email = item.json;
  const sender = (email.from || email.sender || '').toLowerCase();
  const subject = (email.subject || '').toLowerCase();
  const body = (email.text || email.body || '').toLowerCase();

  // 1. Hard Bounce Detection
  const isBounce = /mailer-daemon|postmaster|delivery-notification/i.test(sender) ||
                   /delivery status notification|failure notice|undelivered mail|returned mail|message not delivered/i.test(subject);

  // 2. Out of Office / Auto-responder
  const isOOO = !isBounce && (/automatic reply|auto-reply|out of office|away from office|vacation response/i.test(subject) ||
                /i am currently out of the office|i will be away|limited access to email/i.test(body));

  const classification = isBounce ? 'BOUNCE' : (isOOO ? 'OUT_OF_OFFICE' : 'HUMAN_REPLY');

  return {
    json: {
      ...email,
      event_type: classification,
      is_bounce: isBounce,
      is_ooo: isOOO,
      is_human: classification === 'HUMAN_REPLY'
    }
  };
});

const staticData = $getWorkflowStaticData('global');
staticData.isPaused = true;
staticData.killSwitchActive = true;
staticData.pauseReason = `Hard bounce detected on ${$json.recipient_email || 'recipient'}`;
staticData.pausedAt = new Date().toISOString();

return [{
  json: {
    status: 'KILL_SWITCH_ENGAGED',
    reason: staticData.pauseReason,
    paused_at: staticData.pausedAt
  }
}];

