const res = $input.first().json;
let parsed = {};
try {
  const content = res.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { intent: 'QUESTION', summary: 'Could not parse intent structure', suggested_action: 'Review manually' };
}

return [{
  json: {
    ...$('Switch: By Event Type').item.json,
    ai_intent: parsed.intent || 'QUESTION',
    ai_summary: parsed.summary || '',
    ai_suggested_action: parsed.suggested_action || '',
    ai_confidence: parsed.confidence || 0.8
  }
}];

